WITH joined AS (SELECT e.*, a.balance FROM transactions e JOIN accounts a ON e.account_id = a.id), scored AS (SELECT *, SUM(amount) OVER (PARTITION BY account_id ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount, ROUND(amount / SUM(amount) OVER (PARTITION BY txn_type), 4) AS amount_share, PERCENT_RANK() OVER (PARTITION BY txn_type, merchant ORDER BY amount NULLS LAST) AS amount_percent_rank FROM joined), joined_transactions AS (SELECT e.*, p.balance AS account_balance, p.account_type FROM scored e JOIN accounts p ON e.account_id = p.id), ranked AS (SELECT * FROM joined_transactions QUALIFY RANK() OVER (PARTITION BY merchant, account_type ORDER BY txn_time DESC) = 1), enriched AS (SELECT *, AVG(balance) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS balance_avg_5, ROW_NUMBER() OVER w_running AS seq_no FROM ranked WINDOW w_running AS (ORDER BY txn_time DESC, id)), scored_transactions AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY amount DESC, id) AS event_seq, LAG(amount, 1) OVER (ORDER BY running_amount, id) AS prev_amount FROM enriched) SELECT s.id, s.account_id, s.txn_type, s.amount, s.is_flagged, s.balance, s.amount_share, s.account_balance, s.account_type, (SELECT MAX(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS max_transaction_amount FROM scored_transactions s;
